import{G as e,b as r,c as o,ae as a}from"./chunks/framework.zcMNGGve.js";const d=JSON.parse('{"title":"GitHub 热门 AI 项目（2026 年第 42 周）","description":"","frontmatter":{"title":"GitHub 热门 AI 项目（2026 年第 42 周）","date":"2026/10/12","author":"花木凋零成兰","tags":["GitHub","AI","周刊","Agent"],"hiddenCover":true},"headers":[],"relativePath":"GitHub相关/2026/GitHub热门AI项目（2026年第42周）.md","filePath":"GitHub相关/2026/GitHub热门AI项目（2026年第42周）.md","lastUpdated":1791768327000}'),l={name:"GitHub相关/2026/GitHub热门AI项目（2026年第42周）.md"};function n(i,t,s,g,u,h){return r(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1791763200000"},[...t[0]||(t[0]=[a('<h1 id="github-热门-ai-项目-2026-年第-42-周" tabindex="-1">GitHub 热门 AI 项目（2026 年第 42 周） <a class="header-anchor" href="#github-热门-ai-项目-2026-年第-42-周" aria-label="Permalink to &quot;GitHub 热门 AI 项目（2026 年第 42 周）&quot;">​</a></h1><blockquote><p>数据来源：GitHub Trending 周榜（2026 年第 42 周）。Star 数为周榜快照值，周增量为当周新增数据，适合观察趋势。</p></blockquote><p>本周主线：<strong>Agent 技能生态集中爆发</strong>——mattpocock/skills 单周新增超 9 千 Star 登顶，把&quot;真实工程师私藏的 Agent 技能&quot;推向聚光灯下；claude-mem 延续强势，Agent 跨会话记忆仍是核心叙事；text-to-cad、hyperframes 则让 Agent 的能力边界继续向 CAD、视频生成等专业领域延伸，&quot;Agent 技能&quot;从聚合仓库走向垂直场景。</p><h2 id="项目清单" tabindex="-1">项目清单 <a class="header-anchor" href="#项目清单" aria-label="Permalink to &quot;项目清单&quot;">​</a></h2><h3 id="_1-skills-mattpocock-skills" tabindex="-1">1. Skills（mattpocock/skills） <a class="header-anchor" href="#_1-skills-mattpocock-skills" aria-label="Permalink to &quot;1. Skills（mattpocock/skills）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/mattpocock/skills" target="_blank" rel="noreferrer">https://github.com/mattpocock/skills</a></li><li><strong>Star 数</strong>：286,175（本周 +9,179）</li><li><strong>项目简介</strong>：面向真实工程师的 Agent 技能合集，直接来自作者本人的 .agents 目录。</li><li><strong>本周热度亮点</strong>：单周新增超 9 千 Star 强势登顶，个人级 Agent 技能库成为&quot;工程师日常用 AI&quot;的最佳实践样本。</li><li><strong>技术栈</strong>：Shell</li></ul><h3 id="_2-claude-mem-thedotmack-claude-mem" tabindex="-1">2. Claude-Mem（thedotmack/claude-mem） <a class="header-anchor" href="#_2-claude-mem-thedotmack-claude-mem" aria-label="Permalink to &quot;2. Claude-Mem（thedotmack/claude-mem）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/thedotmack/claude-mem" target="_blank" rel="noreferrer">https://github.com/thedotmack/claude-mem</a></li><li><strong>Star 数</strong>：99,729（本周 +4,035）</li><li><strong>项目简介</strong>：为每个 Agent 提供跨会话持久上下文：捕获会话期间的全部行为，用 AI 压缩，并注入相关上下文到未来会话，兼容 Claude Code、OpenClaw、Codex、Gemini、Copilot 等。</li><li><strong>本周热度亮点</strong>：单周新增 4 千 Star 稳居前列，&quot;Agent 长记忆&quot;从概念落地为通用基础设施，跨工具兼容成为标配。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_3-hyperframes-heygen-com-hyperframes" tabindex="-1">3. Hyperframes（heygen-com/hyperframes） <a class="header-anchor" href="#_3-hyperframes-heygen-com-hyperframes" aria-label="Permalink to &quot;3. Hyperframes（heygen-com/hyperframes）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/heygen-com/hyperframes" target="_blank" rel="noreferrer">https://github.com/heygen-com/hyperframes</a></li><li><strong>Star 数</strong>：60,955（本周 +4,081）</li><li><strong>项目简介</strong>：写 HTML 就能渲染视频，专为 Agent 打造的视频生成框架。</li><li><strong>本周热度亮点</strong>：连续第二周上榜且周增量破 4 千，&quot;Agent 直接产出视频&quot;把多模态内容生成稳定融入 Agent 工作流。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_4-text-to-cad-earthtojake-text-to-cad" tabindex="-1">4. Text-to-CAD（earthtojake/text-to-cad） <a class="header-anchor" href="#_4-text-to-cad-earthtojake-text-to-cad" aria-label="Permalink to &quot;4. Text-to-CAD（earthtojake/text-to-cad）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/earthtojake/text-to-cad" target="_blank" rel="noreferrer">https://github.com/earthtojake/text-to-cad</a></li><li><strong>Star 数</strong>：19,249（本周 +2,369）</li><li><strong>项目简介</strong>：给 Agent 装上 CAD 超能力，用自然语言驱动计算机辅助设计。</li><li><strong>本周热度亮点</strong>：单周新增近 2.4 千 Star，Agent 能力边界向专业设计软件渗透，垂直领域技能持续吸粉。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_5-openrig-mvschwarz-openrig" tabindex="-1">5. OpenRig（mvschwarz/openrig） <a class="header-anchor" href="#_5-openrig-mvschwarz-openrig" aria-label="Permalink to &quot;5. OpenRig（mvschwarz/openrig）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/mvschwarz/openrig" target="_blank" rel="noreferrer">https://github.com/mvschwarz/openrig</a></li><li><strong>Star 数</strong>：6,967（本周 +2,068）</li><li><strong>项目简介</strong>：基于 Claude Code、Codex 与 Pi 构建自有 Agent 网络：带角色、共享上下文与自主工作的持久化团队。</li><li><strong>本周热度亮点</strong>：连续上榜，单周新增 2 千 Star，多 Agent 组队协作的产品化探索持续获得市场认可。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_6-cursor-plugins-cursor-plugins" tabindex="-1">6. Cursor Plugins（cursor/plugins） <a class="header-anchor" href="#_6-cursor-plugins-cursor-plugins" aria-label="Permalink to &quot;6. Cursor Plugins（cursor/plugins）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/cursor/plugins" target="_blank" rel="noreferrer">https://github.com/cursor/plugins</a></li><li><strong>Star 数</strong>：10,897（本周 +1,110）</li><li><strong>项目简介</strong>：Cursor 插件规范与官方插件集合。</li><li><strong>本周热度亮点</strong>：AI 编辑器头部玩家开放插件生态，官方规范发布带动&quot;编辑器即 Agent 平台&quot;的生态建设。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_7-asd-ste100-skill-danyuchn-asd-ste100-skill" tabindex="-1">7. ASD-STE100 Skill（danyuchn/asd-ste100-skill） <a class="header-anchor" href="#_7-asd-ste100-skill-danyuchn-asd-ste100-skill" aria-label="Permalink to &quot;7. ASD-STE100 Skill（danyuchn/asd-ste100-skill）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/danyuchn/asd-ste100-skill" target="_blank" rel="noreferrer">https://github.com/danyuchn/asd-ste100-skill</a></li><li><strong>Star 数</strong>：4,467（本周 +945）</li><li><strong>项目简介</strong>：将 ASD-STE100 简化技术英语规范改造为 Claude Code 技能，用于重写语义模糊的 Agent 面向英文。</li><li><strong>本周热度亮点</strong>：&quot;给 Agent 立语言规矩&quot;成为新需求，工程规范类技能开始进入 Agent 技能生态。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_8-billion-context-ranxianglei-billion-context" tabindex="-1">8. Billion-Context（ranxianglei/billion-context） <a class="header-anchor" href="#_8-billion-context-ranxianglei-billion-context" aria-label="Permalink to &quot;8. Billion-Context（ranxianglei/billion-context）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/ranxianglei/billion-context" target="_blank" rel="noreferrer">https://github.com/ranxianglei/billion-context</a></li><li><strong>Star 数</strong>：901（本周 +259）</li><li><strong>项目简介</strong>：面向小上下文窗口的上下文压缩插件：100K 上下文足矣、省 5 倍 token，并支撑数月级别的超长会话（数十亿 token）。</li><li><strong>本周热度亮点</strong>：新面孔上榜，上下文压缩与超长会话管理成为 Agent 记忆之外的另一条解决路径。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h2 id="本周趋势总结" tabindex="-1">本周趋势总结 <a class="header-anchor" href="#本周趋势总结" aria-label="Permalink to &quot;本周趋势总结&quot;">​</a></h2><ol><li><strong>Agent 技能生态集中爆发</strong>：mattpocock/skills 单周超 9 千 Star 登顶，ASD-STE100 skill、Cursor 插件规范同步上榜，&quot;技能&quot;成为本周最大叙事，从聚合仓库走向个人精品与官方规范。</li><li><strong>Agent 记忆与上下文双线并进</strong>：claude-mem 跨会话持久记忆延续强势，billion-context 以压缩思路解决长上下文，&quot;记什么&quot;与&quot;省多少&quot;成为 Agent 长会话的两个抓手。</li><li><strong>Agent 能力边界向专业领域延伸</strong>：text-to-cad 进入 CAD 设计、hyperframes 连续两周霸榜视频生成，多模态与专业工具集成持续拓宽 Agent 的实用范围。</li><li><strong>多 Agent 协作保持热度</strong>：openrig 连续上榜，带角色、共享上下文的持久化 Agent 团队模式继续推进。</li><li><strong>工程化规范意识抬头</strong>：从技能规范（ASD-STE100）到插件规范（Cursor plugins），&quot;给 Agent 立规矩&quot;与&quot;平台开放生态&quot;并行的信号明显。</li></ol><blockquote><p>注：以上 Star 数与周增量为 GitHub Trending 周榜快照值，仅供参考。 <em>（内容由AI生成，仅供参考）</em></p></blockquote>',23)])])}const m=e(l,[["render",n]]);export{d as __pageData,m as default};
